def parse_conflicts(text: str) -> list:
    lines = text.split('\n')
    conflicts = []
    i = 0
    while i < len(lines):
        if lines[i].startswith('<<<<<<<'):
            start = i
            current_lines = []
            incoming_lines = []
            i += 1
            while i < len(lines) and not lines[i].startswith('======='):
                current_lines.append(lines[i])
                i += 1
            i += 1  # skip =======
            while i < len(lines) and not lines[i].startswith('>>>>>>>'):
                incoming_lines.append(lines[i])
                i += 1
            conflicts.append({
                'current': '\n'.join(current_lines),
                'incoming': '\n'.join(incoming_lines),
                'lineStart': start
            })
        i += 1
    return conflicts

def resolve_conflicts(text: str, strategy: str) -> str:
    lines = text.split('\n')
    result = []
    mode = 'normal'

    for line in lines:
        if line.startswith('<<<<<<<'):
            mode = 'current'
        elif line.startswith('=======') and mode == 'current':
            mode = 'incoming'
        elif line.startswith('>>>>>>>') and mode == 'incoming':
            mode = 'normal'
        elif mode == 'normal':
            result.append(line)
        elif mode == 'current' and strategy in ('current', 'both'):
            result.append(line)
        elif mode == 'incoming' and strategy in ('incoming', 'both'):
            result.append(line)

    return '\n'.join(result)

