function parseConflicts(text) {
  const lines = text.split('\n');
  const conflicts = [];
  let i = 0;
  while (i < lines.length) {
    if (lines[i].startsWith('<<<<<<<')) {
      const start = i;
      const currentLines = [];
      const incomingLines = [];
      i++;
      while (i < lines.length && !lines[i].startsWith('=======')) {
        currentLines.push(lines[i]);
        i++;
      }
      i++;
      while (i < lines.length && !lines[i].startsWith('>>>>>>>')) {
        incomingLines.push(lines[i]);
        i++;
      }
      conflicts.push({
        current: currentLines.join('\n'),
        incoming: incomingLines.join('\n'),
        lineStart: start
      });
    }
    i++;
  }
  return conflicts;
}

function resolveConflicts(text, strategy) {
  const lines = text.split('\n');
  const result = [];
  let mode = 'normal';

  for (const line of lines) {
    if (line.startsWith('<<<<<<<')) {
      mode = 'current';
    } else if (line.startsWith('=======') && mode === 'current') {
      mode = 'incoming';
    } else if (line.startsWith('>>>>>>>') && mode === 'incoming') {
      mode = 'normal';
    } else if (mode === 'normal') {
      result.push(line);
    } else if (mode === 'current' && (strategy === 'current' || strategy === 'both')) {
      result.push(line);
    } else if (mode === 'incoming' && (strategy === 'incoming' || strategy === 'both')) {
      result.push(line);
    }
  }
  return result.join('\n');
}
